const __aivicBundle_14_detectInvoiceDiscrepancies = (() => {
  function detectInvoiceDiscrepancies(
    deals: Array<{
      deal_id: string;
      status: string;
      amount: number;
      invoice_issued_date: string | null;
      expected_invoice_date: string;
      customer_id: string;
      customer_name: string;
    }>
  ): {
    excluded_deals: Array<{ deal_id: string; status: string }>;
    unbilled_deals: Array<{ deal_id: string; status: string }>;
    overdue_invoice_deals: Array<{ deal_id: string; status: string }>;
    total_excluded_count: number;
    total_unbilled_count: number;
    total_overdue_invoice_count: number;
  } {
    const excluded_deals: Array<{ deal_id: string; status: string }> = [];
    const unbilled_deals: Array<{ deal_id: string; status: string }> = [];
    const overdue_invoice_deals: Array<{ deal_id: string; status: string }> = [];
  
    for (const deal of deals) {
      // ステータスが『受注』以外は除外対象
      if (deal.status !== "受注") {
        excluded_deals.push({
          deal_id: deal.deal_id,
          status: deal.status,
        });
        continue;
      }
  
      // ステータスが『受注』の場合、請求書発行状況を判定
      if (deal.invoice_issued_date === null) {
        // 請求書未発行
        unbilled_deals.push({
          deal_id: deal.deal_id,
          status: deal.status,
        });
      } else {
        // 請求書発行済み：期限超過を判定
        const issuedDate = new Date(deal.invoice_issued_date);
        const expectedDate = new Date(deal.expected_invoice_date);
  
        if (issuedDate > expectedDate) {
          // 発行日が期待日を超過している
          overdue_invoice_deals.push({
            deal_id: deal.deal_id,
            status: deal.status,
          });
        }
      }
    }
  
    return {
      excluded_deals,
      unbilled_deals,
      overdue_invoice_deals,
      total_excluded_count: excluded_deals.length,
      total_unbilled_count: unbilled_deals.length,
      total_overdue_invoice_count: overdue_invoice_deals.length,
    };
  }
  return { detectInvoiceDiscrepancies };
})();
