const __aivicBundle_19_reconcileDealsWithInvoices = (() => {
  function reconcileDealsWithInvoices(
    deals: Array<{
      deal_id: string;
      customer_id: string;
      customer_name: string;
      deal_amount: number;
      planned_invoice_date: Date;
      actual_invoice_date: Date;
      deal_status: string;
    }>
  ): Array<{
    deal_id: string;
    customer_id: string;
    customer_name: string;
    deal_amount: number;
    planned_invoice_date: Date;
    actual_invoice_date: Date;
    deal_status: string;
    days_difference: number;
    invoice_status: string;
    reconciliation_status: string;
    reconciliation_timestamp: Date;
  }> {
    const reconciliationTimestamp = new Date();
  
    return deals.map((deal) => {
      const plannedTime = deal.planned_invoice_date.getTime();
      const actualTime = deal.actual_invoice_date.getTime();
      const timeDiffMs = actualTime - plannedTime;
      const daysDifference = Math.ceil(timeDiffMs / (1000 * 60 * 60 * 24));
  
      let invoiceStatus: string;
      let reconciliationStatus: string;
  
      if (daysDifference === 0) {
        invoiceStatus = '予定通り請求';
        reconciliationStatus = '正常';
      } else if (daysDifference > 0) {
        invoiceStatus = '遅延';
        reconciliationStatus = '要確認';
      } else {
        invoiceStatus = '早期請求';
        reconciliationStatus = '要確認';
      }
  
      return {
        deal_id: deal.deal_id,
        customer_id: deal.customer_id,
        customer_name: deal.customer_name,
        deal_amount: deal.deal_amount,
        planned_invoice_date: deal.planned_invoice_date,
        actual_invoice_date: deal.actual_invoice_date,
        deal_status: deal.deal_status,
        days_difference: daysDifference,
        invoice_status: invoiceStatus,
        reconciliation_status: reconciliationStatus,
        reconciliation_timestamp: reconciliationTimestamp,
      };
    });
  }
  return { reconcileDealsWithInvoices };
})();
