/* AIVIC_FUNCTION_BUNDLE_START owner=detectMismatchesBetweenDealStatusAndInvoice exports=detectMismatchesBetweenDealStatusAndInvoice */
const __aivicBundle_21_detectMismatchesBetweenDealStatusAndInvoice = (() => {
  function detectMismatchesBetweenDealStatusAndInvoice(
    deals: DealRecord[],
    invoices: InvoiceRecord[]
  ): DiscrepancyResult[] {
    // 商談レコードが空の場合は空配列を返す
    if (!deals || deals.length === 0) {
      return [];
    }
  
    // 請求書を dealId でマップ化して高速検索
    const invoicesByDealId = new Map<string, InvoiceRecord[]>();
    if (invoices && invoices.length > 0) {
      invoices.forEach((invoice) => {
        const key = invoice.dealId;
        if (!invoicesByDealId.has(key)) {
          invoicesByDealId.set(key, []);
        }
        invoicesByDealId.get(key)!.push(invoice);
      });
    }
  
    const results: DiscrepancyResult[] = [];
  
    deals.forEach((deal) => {
      const dealInvoices = invoicesByDealId.get(deal.dealId) || [];
      const unInvoicedDeals: any[] = [];
      const delayedDeals: any[] = [];
      const matchingDeals: any[] = [];
  
      // 請求書がない場合：未請求
      if (dealInvoices.length === 0) {
        unInvoicedDeals.push({
          dealId: deal.dealId,
          dealStatus: deal.dealStatus,
          dealAmount: deal.dealAmount,
          customerId: deal.customerId,
          customerName: deal.customerName,
          invoiceStatus: deal.invoiceStatus || "未請求",
        });
      } else {
        // 請求書がある場合：金額と日付を照合
        dealInvoices.forEach((invoice) => {
          const amountMatch =
            deal.dealAmount === invoice.invoiceAmount ||
            deal.amount === invoice.amount;
          const invoiceDate =
            invoice.invoiceIssuedDate ||
            invoice.issuedDate ||
            invoice.invoiceDate ||
            invoice.issueDate;
          const plannedDate =
            deal.plannedInvoiceDate ||
            deal.expectedInvoicingDate ||
            deal.billingScheduledDate;
  
          // 金額が一致し、日付が妥当な範囲内なら一致
          if (amountMatch) {
            if (plannedDate && invoiceDate) {
              const delayMs =
                invoiceDate.getTime() - plannedDate.getTime();
              const delayDays = Math.ceil(delayMs / (1000 * 60 * 60 * 24));
  
              // 遅延判定：計画日から30日以上遅れている場合
              if (delayDays > 30) {
                delayedDeals.push({
                  dealId: deal.dealId,
                  dealStatus: deal.dealStatus,
                  dealAmount: deal.dealAmount,
                  customerId: deal.customerId,
                  customerName: deal.customerName,
                  plannedInvoiceDate: plannedDate,
                  actualInvoiceDate: invoiceDate,
                  delayDays: delayDays,
                });
              } else {
                matchingDeals.push({
                  dealId: deal.dealId,
                  dealStatus: deal.dealStatus,
                  dealAmount: deal.dealAmount,
                  invoiceAmount: invoice.invoiceAmount,
                  invoiceId: invoice.invoiceId,
                });
              }
            } else {
              matchingDeals.push({
                dealId: deal.dealId,
                dealStatus: deal.dealStatus,
                dealAmount: deal.dealAmount,
                invoiceAmount: invoice.invoiceAmount,
                invoiceId: invoice.invoiceId,
              });
            }
          } else {
            // 金額が不一致
            delayedDeals.push({
              dealId: deal.dealId,
              dealStatus: deal.dealStatus,
              dealAmount: deal.dealAmount,
              invoiceAmount: invoice.invoiceAmount,
              customerId: deal.customerId,
              customerName: deal.customerName,
              mismatchReason: "金額不一致",
            });
          }
        });
      }
  
      // 結果を集約
      const discrepanciesDetected =
        unInvoicedDeals.length > 0 || delayedDeals.length > 0;
  
      results.push({
        discrepanciesDetected: discrepanciesDetected,
        unInvoicedDeals: unInvoicedDeals,
        delayedDeals: delayedDeals,
        matchingDeals: matchingDeals,
      });
    });
  
    return results;
  }
  return { detectMismatchesBetweenDealStatusAndInvoice };
})();
