const __aivicBundle_22_detectDelayedInvoices = (() => {
  function detectDelayedInvoices(
    deals: Array<{
      deal_id: string;
      customer_name: string;
      status: string;
      amount: number;
      invoice_due_date: string;
      invoice_issued_date: string | null;
      invoice_status: string;
    }>,
    currentDate: Date
  ): Array<{
    deal_id: string;
    customer_name: string;
    status: string;
    amount: number;
    invoice_due_date: string;
    invoice_issued_date: string | null;
    invoice_status: string;
  }> {
    return deals.filter((deal) => {
      const dueDateObj = new Date(deal.invoice_due_date);
      const isOverdue = dueDateObj < currentDate;
      const isNotYetIssued = deal.invoice_issued_date === null;
      return isOverdue && isNotYetIssued;
    });
  }
  return { detectDelayedInvoices };
})();
