const __aivicBundle_23_detectInvoiceDelayedCases = (() => {
  function detectInvoiceDelayedCases(
    dealRecords: Array<{
      dealId: string;
      customerId: string;
      customerName: string;
      dealStatus: string;
      dealAmount: number;
      invoiceScheduledDate: Date;
      invoiceIssuedDate: Date | null;
      invoiceStatus: string;
      createdDate?: Date;
      updatedDate?: Date;
    }>,
    referenceDate: Date
  ): {
    delayedCases: Array<{
      dealId: string;
      customerId: string;
      customerName: string;
      dealStatus: string;
      dealAmount: number;
      invoiceScheduledDate: Date;
      invoiceIssuedDate: Date | null;
      invoiceStatus: string;
      delayStatus?: string;
      reason?: string;
      delayDays?: number;
      delayReason?: string;
      isDelayed?: boolean;
    }>;
    nonDelayedCases: Array<{
      dealId: string;
      customerId: string;
      customerName: string;
      dealStatus: string;
      dealAmount: number;
      invoiceScheduledDate: Date;
      invoiceIssuedDate: Date | null;
      invoiceStatus: string;
      delayStatus?: string;
      reason?: string;
    }>;
    delayedCaseCount: number;
    totalDelayedAmount: number;
    alertNotificationRequired: boolean;
    notificationRecipient: string;
    detectionTimestamp: Date;
    totalDealsChecked?: number;
  } {
    const delayedCases: Array<{
      dealId: string;
      customerId: string;
      customerName: string;
      dealStatus: string;
      dealAmount: number;
      invoiceScheduledDate: Date;
      invoiceIssuedDate: Date | null;
      invoiceStatus: string;
      delayDays?: number;
      delayReason?: string;
    }> = [];
  
    const nonDelayedCases: Array<{
      dealId: string;
      customerId: string;
      customerName: string;
      dealStatus: string;
      dealAmount: number;
      invoiceScheduledDate: Date;
      invoiceIssuedDate: Date | null;
      invoiceStatus: string;
      delayStatus?: string;
      reason?: string;
    }> = [];
  
    let totalDelayedAmount = 0;
  
    for (const deal of dealRecords) {
      const scheduledTime = deal.invoiceScheduledDate.getTime();
      const referenceTime = referenceDate.getTime();
      const isInvoiceUnissued = deal.invoiceIssuedDate === null;
  
      if (scheduledTime < referenceTime && isInvoiceUnissued) {
        const delayMs = referenceTime - scheduledTime;
        const delayDays = Math.floor(delayMs / (1000 * 60 * 60 * 24));
  
        delayedCases.push({
          dealId: deal.dealId,
          customerId: deal.customerId,
          customerName: deal.customerName,
          dealStatus: deal.dealStatus,
          dealAmount: deal.dealAmount,
          invoiceScheduledDate: deal.invoiceScheduledDate,
          invoiceIssuedDate: deal.invoiceIssuedDate,
          invoiceStatus: deal.invoiceStatus,
          delayDays,
          delayReason: '請求予定日超過',
        });
  
        totalDelayedAmount += deal.dealAmount;
      } else {
        let reason = '';
        if (scheduledTime === referenceTime) {
          reason = '請求予定日が当日のため対象外';
        } else if (scheduledTime > referenceTime) {
          reason = '請求予定日が未来のため対象外';
        } else if (deal.invoiceIssuedDate !== null) {
          reason = '請求書が既に発行されているため対象外';
        }
  
        nonDelayedCases.push({
          dealId: deal.dealId,
          customerId: deal.customerId,
          customerName: deal.customerName,
          dealStatus: deal.dealStatus,
          dealAmount: deal.dealAmount,
          invoiceScheduledDate: deal.invoiceScheduledDate,
          invoiceIssuedDate: deal.invoiceIssuedDate,
          invoiceStatus: deal.invoiceStatus,
          delayStatus: '遅延なし',
          reason,
        });
      }
    }
  
    const alertNotificationRequired = delayedCases.length > 0;
    const notificationRecipient = alertNotificationRequired ? 'management' : '';
  
    const detectionTimestamp = new Date(referenceDate);
    detectionTimestamp.setUTCHours(0, 0, 0, 0);
  
    return {
      delayedCases,
      nonDelayedCases,
      delayedCaseCount: delayedCases.length,
      totalDelayedAmount,
      alertNotificationRequired,
      notificationRecipient,
      detectionTimestamp,
      totalDealsChecked: dealRecords.length,
    };
  }
  return { detectInvoiceDelayedCases };
})();
