const __aivicBundle_38_calculateAnnualSavingsAndROI = (() => {
  function calculateAnnualSavingsAndROI(input: {
    inHouseSystemAnnualOperationCost?: number;
    salesforceAnnualLicenseCost?: number;
    currentSalesforceAnnualCost?: number;
    systemDevelopmentCost?: number;
    systemAnnualMaintenanceCost?: number;
    projectionYears?: number;
  }): {
    annualSavings: number;
    roiPercentage: number;
    totalCumulativeSavings?: number;
    roi?: number;
    paybackYears?: number;
  } {
    const inHouseAnnualCost = input.inHouseSystemAnnualOperationCost ?? 0;
    const salesforceAnnualCost = input.salesforceAnnualLicenseCost ?? 0;
    const developmentCost = input.systemDevelopmentCost ?? 0;
    const maintenanceCost = input.systemAnnualMaintenanceCost ?? 0;
    const years = input.projectionYears ?? 1;
  
    const annualSavings = Math.max(0, salesforceAnnualCost - inHouseAnnualCost);
    const roiPercentage = developmentCost === 0 ? 0 : (annualSavings / developmentCost) * 100;
  
    let totalCumulativeSavings = 0;
    let paybackYears = 0;
    let remainingInvestment = developmentCost;
  
    for (let year = 1; year <= years; year++) {
      const yearlySystemCost = developmentCost + maintenanceCost;
      const yearlySavings = annualSavings - (year === 1 ? yearlySystemCost : maintenanceCost);
      totalCumulativeSavings += Math.max(0, yearlySavings);
  
      if (paybackYears === 0 && remainingInvestment > 0) {
        if (yearlySavings >= remainingInvestment) {
          paybackYears = year - 1 + (remainingInvestment / yearlySavings);
        } else {
          remainingInvestment -= yearlySavings;
        }
      }
    }
  
    const roi = developmentCost === 0 ? 0 : (totalCumulativeSavings / developmentCost) * 100;
  
    return {
      annualSavings,
      roiPercentage,
      totalCumulativeSavings,
      roi,
      paybackYears: paybackYears > 0 ? paybackYears : years,
    };
  }
  return { calculateAnnualSavingsAndROI };
})();
